/* ===== Phase 12: Hard problems ===== */
P(12,{key:'Design Location Based Service like Yelp',short:'Yelp (Proximity)',
  lead:'Design a proximity service: given a location and radius, find nearby businesses quickly, show details and reviews, and let owners update listings. Meta has asked "proximity service" per a Blind report.',
  more:['The heart is a geospatial index. Geohash encodes locations as strings where shared prefixes mean nearby cells; a search covers the user\'s cell and its neighbours. Quadtrees split space adaptively so dense cities get small cells; Google S2 maps the sphere to cells on a Hilbert curve. Businesses change rarely, so the index can be built and replicated read-only, with updates applied on a schedule. Reads dominate; caching by cell helps.'],
  clarify:[['Scale?','200 million businesses, 100K searches per second.'],['Radius options?','0.5 to 20 km.'],['Freshness of listing changes?','Next day is acceptable.'],['Ranking?','By distance and rating.']],
  est:{dau:100e6,writes:0.001,ratio:50000,size:2000,years:0,peak:3,wlabel:'business updates',rlabel:'searches',unit:'business record'},
  build:B(['Geospatial index (geohash, quadtree or S2) | Find nearby businesses without scanning all.','Location service replicas serving the index from memory | High read throughput.','Business details DB plus cache | Rich data for results.','Reviews service | User content.','Batch or periodic index rebuild from updates | Businesses change rarely.','Cache of results by cell and radius | Popular areas repeat.'],['Computing distance to every business | Too slow.','Strong consistency for listing edits | Next-day freshness is fine.','Sharding by business id for geo queries | A query would touch every shard.']),
  takeaway:'Index locations with geohash, quadtrees or S2, serve the read-only index from replicated memory, cache by cell, and rebuild periodically from business updates.',
  pre:['Database Indexes','Database Replication','Caching 101'],
  quiz:[{q:'Why search the neighbouring geohash cells too?',o:['For fun','A nearby business can sit just across a cell boundary','Geohash requires 9 cells always'],a:1,why:'Proximity does not respect cell borders.',hint:'Edges.'},
        {q:'What advantage does a quadtree have over fixed-size geohash cells?',o:['Simpler','Adapts cell size to density, so dense cities get small cells and deserts big ones','Uses less memory always'],a:1,why:'Balances the number of businesses per cell.',hint:'Density varies.'}],
  terms:[['Geohash','Base32 string encoding of a lat/long cell.'],['Quadtree','Tree splitting space into four quadrants recursively.'],['S2','Hierarchical cells on a sphere.']],
  deep:[{h:'Index options',ul:['Geohash: simple, string prefixes; boundary and density issues.','Quadtree: in-memory tree, split cells over a threshold.','S2: good for arbitrary regions and covers.','Database geo indexes (PostGIS, Redis GEO) for smaller scale.']},
   {h:'Serving',ul:['Index about a few GB fits in memory; replicate widely.','Query: covering cells for radius, fetch ids, filter by exact distance, rank.','Hydrate details from cache.']},
   {h:'Updates',ul:['Owner edits to the business DB.','Nightly rebuild or incremental updates to the index.','Blue-green swap of index versions.']},
   {h:'Scale',ul:['Read replicas per region.','Results cache keyed by cell and filters.','Ranking service for relevance.']}],
  iq:[{q:'Explain geohash and how a radius search works.',lvl:'Mid',cover:['Encoding, precision levels, neighbours.','Filtering by exact distance.'],pitfalls:['Only searching one cell.']},
   {q:'Design the proximity service end to end.',cover:['Index choice and serving.','Details, reviews, caching.','Updates and freshness.'],pitfalls:['Database scans.']},
   {q:'Extend to real-time moving objects (delivery drivers) at 1 million updates per second.',lvl:'Staff+',cover:['In-memory geo index updated continuously, sharded by region cell.','Update batching; TTLs for stale positions.','Hot cells (city centres) split further.','Different from static business index.'],pitfalls:['Rebuilding a static index per update.']}]});

P(12,{key:'Design Uber',short:'Uber',
  lead:'Design ride hailing: riders request trips, the system matches them with nearby drivers in seconds, tracks the trip live, prices it (including surge), and handles payment. A Blind report noted interviewers probing scaling by coordinates and matching driver direction to demand.',
  more:['Drivers send locations every few seconds; an in-memory geospatial index (S2 or H3 cells, sharded by region) keeps current positions. A ride request finds candidate drivers in nearby cells, ranks them by ETA (not straight-line distance), and offers the trip to one driver at a time or a few in parallel, with a lock so a driver is never matched twice. Trip state is a state machine stored durably; locations and events stream to pricing (surge per cell), ETA models and analytics.'],
  clarify:[['Scale?','Assume 20 million trips a day, 5 million active drivers sending locations every 4 seconds.'],['Matching latency?','A few seconds.'],['Pricing?','Surge by area and time.'],['Payments?','At trip end, via payment system.']],
  est:{dau:5e6,writes:21600,ratio:0.01,size:100,years:0,peak:2,wlabel:'driver location updates',rlabel:'match queries',unit:'location update'},
  build:B(['Driver location ingestion over persistent connections | Millions of updates per second.','In-memory geo index sharded by region cells (S2/H3) | Fast nearby-driver lookup.','Matching service ranking by ETA with driver locking | One trip per driver, best pickup time.','Trip service with a durable state machine | Correct lifecycle across failures.','Surge pricing from supply and demand per cell (streaming) | Balance the market.','Payments at trip end via saga | Money flow.'],['Storing every location update in a relational database synchronously | Write volume far too high.','Matching by straight-line distance only | Ignores roads and direction.','Offering one trip to many drivers with no locking | Double assignment.']),
  takeaway:'Stream driver locations into a sharded in-memory geo index, match by ETA with locking, run trips as durable state machines, and compute pricing from streams.',
  pre:['Design Location Based Service like Yelp','WebSockets','Distributed Locking'],
  quiz:[{q:'Why rank drivers by ETA rather than distance?',o:['It is cheaper','A driver 1 km away across a river may take longer than one 2 km away on the same road','Distance is unknown'],a:1,why:'Pickup time is what riders feel.',hint:'Roads.'},
        {q:'How do you stop one driver being matched to two riders?',o:['Hope','Atomically claim the driver (lock or conditional state change) before offering','Assign in a nightly batch'],a:1,why:'Driver availability must be updated atomically.',hint:'Race.'}],
  terms:[['H3 / S2','Hierarchical geo cell systems.'],['ETA','Estimated time of arrival.'],['Surge','Dynamic price multiplier when demand exceeds supply.']],
  deep:[{h:'Locations',ul:['Driver app sends position every few seconds over a persistent connection.','Update in-memory index (cell to drivers); keep latest only; TTL.','Stream to Kafka for analytics, ETA training, surge.']},
   {h:'Matching',ul:['Find drivers in rider cell and rings around it.','Compute ETAs with a routing service; filter by vehicle type.','Claim driver; send offer; timeout and move to next.','Batch matching in dense areas for global efficiency.']},
   {h:'Trips',ul:['States: requested, matched, en route, in progress, completed, cancelled.','Stored in a durable, partitioned store; events emitted.','Live location shared with the rider.']},
   {h:'Reliability',ul:['Region-level isolation; failover of matching state.','Phones resume trips from server state.','Payments idempotent; fraud checks.']}],
  iq:[{q:'Design driver location updates and nearby-driver search.',lvl:'Mid',cover:['Update path; geo index.','Search by cells.'],pitfalls:['Database writes per update.']},
   {q:'Design matching with fairness and no double assignment.',cover:['ETA ranking, claim/lock, offers with timeouts.','Batch matching.','Failure handling.'],pitfalls:['No locking.']},
   {q:'Design surge pricing that updates every minute per neighbourhood.',lvl:'Staff+',cover:['Streaming supply and demand per cell; windows.','Smoothing to avoid oscillation; caps; explainability.','Price locked when the rider requests.','Experiments and monitoring.'],pitfalls:['Recomputing from the database per request.']}]});

P(12,{key:'Design Food Delivery App like Doordash',short:'Food Delivery',
  lead:'Design food delivery: customers browse nearby restaurants and menus, order, restaurants accept and prepare, couriers are assigned and tracked, and everyone gets live status, with payment captured at the end.',
  more:['It combines a marketplace (restaurant search by location and opening hours), an order lifecycle that spans three parties, and a dispatch problem: choosing which courier picks up which order, considering preparation time, travel time and batching several orders. Orders are orchestrated as a saga with clear states and timeouts (restaurant does not accept in 5 minutes). Courier locations are handled like Uber\'s; ETAs combine prep and travel predictions.'],
  clarify:[['Scale?','Assume 5 million orders a day, peaks at lunch and dinner.'],['Dispatch?','Automatic with batching of nearby orders.'],['Live tracking?','Yes for customers.'],['Payments?','Authorise at order, capture on delivery.']],
  est:{dau:20e6,writes:0.25,ratio:40,size:3000,years:5,peak:4,wlabel:'orders',rlabel:'status and menu reads',unit:'order'},
  build:B(['Restaurant search with geo index and hours | Show what can deliver now.','Menu service with caching | Read-heavy browsing.','Order orchestrator (saga) with states and timeouts | Coordinate customer, restaurant, courier.','Dispatch service using prep and travel ETAs with batching | Efficient courier assignment.','Courier location tracking (in-memory geo index) | Live updates and matching.','Payment authorise/capture with idempotency | Correct charges.'],['Assigning a courier the moment the order is placed regardless of prep time | Couriers wait at restaurants.','A single synchronous call chain across all parties | Fragile.','Polling the database for courier positions | Too slow.']),
  takeaway:'Geo search for restaurants, an orchestrated order saga with timeouts, dispatch that times courier arrival to food readiness, live tracking, and authorise-then-capture payments.',
  pre:['Design Uber','Event-Driven Architecture','Design Payment System'],
  quiz:[{q:'Why consider preparation time when assigning couriers?',o:['It does not matter','So couriers arrive when food is ready rather than waiting or arriving late','To reduce app size'],a:1,why:'Dispatch optimises the whole delivery time.',hint:'Kitchen and road.'},
        {q:'What happens if the restaurant does not accept within 5 minutes?',o:['Wait forever','A timeout in the order saga cancels or reassigns and voids the payment authorisation','Charge anyway'],a:1,why:'Orchestration with timeouts and compensation.',hint:'Saga timeouts.'}],
  terms:[['Dispatch','Assigning couriers to orders.'],['Order batching','One courier carrying several orders.'],['Authorise/capture','Hold funds first, charge later.']],
  deep:[{h:'Order lifecycle',ul:['Placed, accepted, preparing, courier assigned, picked up, delivered, cancelled.','Orchestrator (Temporal-like) drives steps and timeouts.','Events for notifications and analytics.']},
   {h:'Dispatch',ul:['Predict prep time per restaurant and order.','Candidates by courier location and ETA; batch compatible orders.','Optimise periodically (every few seconds) across many orders.']},
   {h:'Tracking',ul:['Courier locations streamed; customer app subscribes.','ETA updates from models.']},
   {h:'Peaks',ul:['Restaurant load awareness; throttle orders to busy kitchens.','Courier incentives; surge fees.','Capacity planning for meal peaks.']}],
  iq:[{q:'Design the order lifecycle across customer, restaurant and courier.',lvl:'Mid',cover:['States and transitions.','Notifications.','Timeouts.'],pitfalls:['No timeouts or cancellations.']},
   {q:'Design the dispatch algorithm and its data needs.',cover:['ETAs for prep and travel.','Batching and assignment optimisation.','Feedback from outcomes.'],pitfalls:['Nearest courier only.']},
   {q:'Dinner peaks overload restaurants and couriers in one city. What system-level controls do you add?',lvl:'Staff+',cover:['Kitchen capacity signals and order throttling.','Dynamic delivery fees and radius shrinking.','Courier supply incentives.','Clear customer ETAs; monitoring.'],pitfalls:['Accepting all orders and missing ETAs.']}]});

P(12,{key:'Design Google Docs',short:'Google Docs',
  lead:'Design collaborative document editing: many users edit the same document at once and see each other\'s changes and cursors in real time, with offline edits, history and permissions. Palantir has asked this per a Blind report.',
  more:['Concurrent edits conflict: two users inserting at the same position. Operational transformation (OT) transforms operations against each other on a central server so all replicas converge; CRDTs give each character a unique position identifier so replicas merge without a central transform. Each open document is handled by one collaboration server (route by document id), which orders operations, broadcasts them over WebSockets, and persists an operation log plus periodic snapshots.'],
  clarify:[['Concurrent editors per doc?','Up to 100.'],['Offline editing?','Yes, with merge on reconnect.'],['History?','Full version history.'],['Rich text?','Yes.']],
  est:{dau:50e6,writes:500,ratio:5,size:100,years:3,peak:3,wlabel:'edit operations',rlabel:'operation broadcasts',unit:'operation'},
  build:B(['Collaboration servers holding active documents, routed by document id | One place orders operations per doc.','OT or CRDT algorithm | Converge despite concurrent edits.','WebSockets to clients for operations and cursors | Real-time updates.','Operation log plus periodic snapshots | Durability, history and fast loading.','Permissions service | Who can view or edit.','Offline queue on client with rebase/merge on reconnect | Edit without connection.'],['Locking the whole document while one user types | Not collaborative.','Last-write-wins on the whole document | Loses edits.','Saving the full document on every keystroke | Wasteful; store operations.']),
  takeaway:'Route each document to one collaboration server, merge concurrent edits with OT or CRDTs, broadcast over WebSockets, and persist an operation log with snapshots.',
  pre:['WebSockets','Stateful vs Stateless Design','Event-Driven Architecture'],
  quiz:[{q:'What problem does operational transformation solve?',o:['Compression','Adjusting concurrent operations so every replica ends in the same state','Authentication'],a:1,why:'Insert positions shift when others edit first.',hint:'Concurrent edits.'},
        {q:'Why route all editors of a document to the same server?',o:['Cheaper hosting','One server can order operations and hold the live state in memory','Browsers require it'],a:1,why:'Central ordering simplifies OT and reduces latency.',hint:'Ordering.'}],
  terms:[['OT','Operational transformation.'],['CRDT','Conflict-free replicated data type.'],['Snapshot','Full document state at a version.']],
  deep:[{h:'Editing protocol',ul:['Client sends operations with the version it is based on.','Server transforms against newer operations, assigns the next version, broadcasts.','Clients transform their pending operations accordingly.']},
   {h:'OT vs CRDT',ul:['OT: compact, central server needed, complex transform functions.','CRDT: peer-friendly, offline-friendly, larger metadata.','Many systems use OT centrally; CRDTs (Yjs, Automerge) are growing.']},
   {h:'Storage',ul:['Append operations to a log per document; snapshot every N operations.','Load = snapshot + later operations.','Version history from snapshots and logs.']},
   {h:'Scaling and failures',ul:['Consistent hashing of documents to servers; move on failure.','Clients reconnect and resend unacknowledged operations.','Presence and cursors as ephemeral messages.']}],
  iq:[{q:'Explain how two people typing at the same position end up with the same text.',lvl:'Mid',cover:['Operations, versions, transforms (or CRDT ids).','Convergence example.'],pitfalls:['Locking.']},
   {q:'Design the backend for real-time collaboration on 10 million active documents.',cover:['Routing, collaboration servers, WebSockets.','Operation log, snapshots.','Failover of a collaboration server.'],pitfalls:['Stateless servers loading the document per keystroke.']},
   {q:'Support offline editing for days and merging on reconnect. OT or CRDT, and why?',lvl:'Staff+',cover:['CRDTs merge without a central transform over long divergence.','OT needs rebasing long operation histories.','Metadata growth and garbage collection.','User experience for conflicts in rich text.'],pitfalls:['Claiming OT handles long offline periods easily.']}]});

P(12,{key:'Design Google Maps',short:'Google Maps',
  lead:'Design a maps service: render maps, search places, compute routes with ETAs that account for live traffic, and give turn-by-turn navigation to hundreds of millions of users.',
  more:['Three systems. Map rendering serves pre-generated vector or raster tiles by zoom level through CDNs. Routing runs shortest-path algorithms on a road graph; plain Dijkstra is too slow on a continent, so systems precompute hierarchies (contraction hierarchies) or partition the graph into regions with shortcuts. Live traffic comes from aggregated, anonymised phone locations streamed into speed estimates per road segment, which update edge weights and ETAs.'],
  clarify:[['Scope?','Tiles, place search, routing, live traffic, navigation.'],['Scale?','1 billion monthly users; 100K route requests per second.'],['Freshness of traffic?','Within minutes.'],['Offline maps?','Mention.']],
  est:{dau:300e6,writes:50,ratio:0.05,size:50,years:0,peak:3,wlabel:'location pings',rlabel:'route requests',unit:'location ping'},
  build:B(['Map tiles by zoom level served via CDN | Fast map display.','Road graph with precomputed hierarchies (contraction hierarchies) | Fast routing over continents.','Routing service computing paths and ETAs | Directions.','Traffic pipeline from anonymised location pings to segment speeds | Live ETAs.','Place search with geo index | Find destinations.','Navigation sessions with rerouting | Turn-by-turn guidance.'],['Running plain Dijkstra over the whole world graph per request | Too slow.','Rendering map images per request on servers | Use pre-generated tiles.','Storing raw location pings forever with identities | Privacy and cost.']),
  takeaway:'Pre-generated tiles via CDN, a preprocessed road graph for fast routing, a streaming traffic pipeline updating edge weights, and geo search for places.',
  pre:['Design Location Based Service like Yelp','Batch vs Stream Processing','Content Delivery Network (CDN)'],
  quiz:[{q:'Why are map tiles pre-generated?',o:['Licensing','Each tile is reused by many users, so render once and serve from CDN','Browsers cannot draw maps'],a:1,why:'Rendering is expensive; tiles are highly cacheable.',hint:'Shared content.'},
        {q:'What makes continent-scale routing fast?',o:['Faster CPUs','Preprocessing the graph (contraction hierarchies, partitions) so queries explore few nodes','Caching every possible route'],a:1,why:'Shortcuts skip most of the graph at query time.',hint:'Preprocessing.'}],
  terms:[['Tile','Square map image or vector data at a zoom level.'],['Contraction hierarchies','Precomputed shortcuts for fast shortest paths.'],['Edge weight','Travel time on a road segment.']],
  deep:[{h:'Tiles',ul:['Zoom levels 0 to about 21; tile coordinates (z, x, y).','Vector tiles styled on the client; raster for legacy.','Generation pipeline when map data changes; CDN caching.']},
   {h:'Routing',ul:['Road graph from map data; edge weights by speed.','Contraction hierarchies or partition-based routing.','Live traffic adjusts weights; alternative routes.']},
   {h:'Traffic',ul:['Phones send anonymised speed samples.','Stream processing aggregates per segment per minute.','Historical patterns for predictions.']},
   {h:'Navigation',ul:['Session with planned route; client follows offline.','Rerouting when off route or traffic changes.','Offline map packages.']}],
  iq:[{q:'Explain map tiles and zoom levels.',lvl:'Mid',cover:['Tile pyramid; coordinates; caching.'],pitfalls:['Rendering per request.']},
   {q:'Design route computation with live traffic.',cover:['Graph preprocessing; dynamic weights.','Customisable contraction hierarchies or partition overlays.','ETA prediction.'],pitfalls:['Dijkstra on the full graph.']},
   {q:'Design the traffic data pipeline with strong privacy guarantees.',lvl:'Staff+',cover:['Anonymisation, aggregation thresholds, trimming trip ends.','Streaming speeds per segment; outlier removal.','Retention limits; differential privacy ideas.'],pitfalls:['Storing identifiable trips.']}]});

P(12,{key:'Design Zoom',short:'Zoom',
  lead:'Design video conferencing: real-time audio and video for meetings from 2 to 1,000 participants, with low latency, adaptation to bad networks, screen sharing, chat and recording.',
  more:['Real-time media uses UDP-based protocols (WebRTC, RTP/SRTP) because a late packet is useless. One-to-one calls can be peer-to-peer; larger meetings go through a selective forwarding unit (SFU): each participant uploads one stream (often simulcast at several qualities) and the SFU forwards the right quality to each receiver based on their bandwidth and layout. Signalling (who joins, which streams) is separate from media. Media servers are placed regionally; cascading SFUs connect participants in different regions.'],
  clarify:[['Meeting size?','Up to 1,000 participants, up to 50 videos shown.'],['Latency?','Under 200 ms mouth-to-ear.'],['Recording?','Yes, to cloud.'],['End-to-end encryption?','Optional.']],
  est:{dau:50e6,writes:1,ratio:10,size:500e6,years:0,peak:3,wlabel:'meetings joined',rlabel:'streams received',unit:'meeting recording'},
  build:B(['Signalling service (WebSocket) for join, mute, layout | Control plane separate from media.','SFU media servers forwarding streams | Scale beyond peer-to-peer.','Simulcast and bandwidth estimation | Each receiver gets a quality it can handle.','Regional media servers with cascading between regions | Low latency for global meetings.','TURN relays for NAT traversal | Connectivity behind firewalls.','Recording service consuming streams to storage | Cloud recordings.'],['TCP for real-time media | Retransmissions add latency.','Full mesh peer-to-peer for 50 participants | Upload explodes.','Mixing every stream on the server (MCU) by default | Expensive CPU; use only where needed.']),
  takeaway:'Separate signalling from media, use UDP with SFUs and simulcast for multiparty calls, place media servers regionally with cascading, and relay when direct connections fail.',
  pre:['Peer-to-Peer (P2P) Architecture','TCP vs UDP','WebSockets'],
  quiz:[{q:'Why do video calls use UDP-based transport?',o:['UDP is encrypted','Late packets are useless for live media, so waiting for retransmissions only adds delay','TCP is not supported in browsers'],a:1,why:'Real-time media prefers timeliness over completeness.',hint:'Late is lost.'},
        {q:'What does an SFU do?',o:['Mixes all videos into one','Receives each participant\'s stream once and forwards selected streams to others','Stores recordings only'],a:1,why:'It scales without heavy server-side decoding.',hint:'Forwarding.'}],
  terms:[['SFU','Selective forwarding unit.'],['Simulcast','Sending the same video at several qualities.'],['Jitter buffer','Smooths packet arrival timing.']],
  deep:[{h:'Media path',ul:['Client encodes video (simulcast layers) and audio.','SFU forwards layers per receiver bandwidth and layout.','Packet loss handled with FEC, NACKs, adaptive bitrate.']},
   {h:'Signalling',ul:['Join, leave, mute, active speaker, layout over WebSockets.','Session description and ICE negotiation.']},
   {h:'Global scale',ul:['Assign meeting to an SFU in a region near most participants.','Cascade SFUs across regions for distant participants.','Capacity per SFU by bitrate and CPU.']},
   {h:'Extras',ul:['Recording bots join as participants.','Large webinars: few speakers, many viewers via streaming.','E2EE with SFUs (insertable streams).']}],
  iq:[{q:'Compare peer-to-peer, SFU and MCU for calls.',lvl:'Mid',cover:['Bandwidth and CPU per participant.','When each fits.'],pitfalls:['P2P for large calls.']},
   {q:'Design a 200-person meeting with participants on three continents.',cover:['Regional SFUs, cascading.','Simulcast and layout-based forwarding.','Signalling and failover.'],pitfalls:['One SFU in one region.']},
   {q:'Users on poor networks report frozen video. Design the adaptation strategy.',lvl:'Staff+',cover:['Bandwidth estimation, simulcast or SVC layers.','Prioritise audio; reduce resolution or frame rate.','FEC vs retransmission trade-offs; telemetry to tune.'],pitfalls:['Only buffering longer.']}]});

P(12,{key:'Design File Sharing System like Dropbox',short:'Dropbox',
  lead:'Design file sync and sharing: users\' files sync across devices, can be shared, keep version history, and upload efficiently even for large files that change slightly.',
  more:['Files are split into chunks (for example 4 MB), each identified by its content hash. Clients upload only chunks the server does not have, which enables deduplication and fast sync of small changes. Metadata (file tree, versions, the list of chunk hashes per file version) lives in a strongly consistent database; chunks live in object storage. A notification service tells other devices that something changed so they fetch the new metadata and missing chunks. Conflicts (two devices editing offline) produce conflict copies.'],
  clarify:[['Max file size?','Up to 50 GB.'],['Scale?','500 million users, 1 PB uploaded a day.'],['Sharing and permissions?','Yes.'],['Conflicts?','Keep both versions.']],
  est:{dau:100e6,writes:5,ratio:2,size:2e6,years:5,peak:3,wlabel:'file changes',rlabel:'downloads and syncs',unit:'changed data'},
  build:B(['Client chunking with content hashes | Upload only changed chunks; deduplicate.','Block (chunk) storage in object storage | Durable, scalable blobs.','Metadata DB with file tree, versions and chunk lists (strongly consistent) | Correct sync state.','Notification service (long poll/WebSocket) for change events | Devices learn about changes quickly.','Sync protocol with cursors per device | Fetch only what changed since last sync.','Sharing and permissions service | Shared folders and links.'],['Uploading the entire file on every change | Slow and wasteful.','Eventual consistency for the file tree metadata | Confusing, lossy sync.','Storing files in the metadata database | Huge blobs in a database.']),
  takeaway:'Chunk files by content hash for dedup and delta sync, keep metadata strongly consistent and chunks in object storage, notify devices of changes, and resolve conflicts with conflict copies.',
  pre:['Checksums','Databases Types','Long Polling vs WebSockets'],
  quiz:[{q:'Why split files into content-addressed chunks?',o:['Encryption','Only changed chunks need uploading, and identical chunks are stored once','Faster directory listing'],a:1,why:'Delta sync and deduplication.',hint:'Same content, same hash.'},
        {q:'How do other devices learn a file changed?',o:['They rescan every file','A notification service signals them, then they fetch metadata changes since their cursor','Email'],a:1,why:'Push signal plus cursor-based sync.',hint:'Push then pull.'}],
  terms:[['Chunk','Fixed or content-defined piece of a file.'],['Content hash','Hash of data used as its identifier.'],['Sync cursor','Position in a change log a device has processed.']],
  deep:[{h:'Upload',ul:['Client computes chunk hashes; asks which are missing.','Uploads missing chunks (pre-signed URLs); commits new file version metadata.','Resumable for large files.']},
   {h:'Metadata',ul:['Namespaces, files, versions, chunk lists; journal of changes per namespace.','Strongly consistent (sharded relational).','Version history and restore.']},
   {h:'Sync and conflicts',ul:['Devices long-poll or hold a connection for change notifications.','Fetch journal entries after cursor; download missing chunks.','Concurrent edits produce conflicted copies.']},
   {h:'Storage efficiency',ul:['Dedup across users (with care for privacy).','Compression; cold tiers for old versions.','Erasure coding in storage.']}],
  iq:[{q:'Design upload and download of large files.',lvl:'Mid',cover:['Chunking, hashing, resumable upload.','Metadata commit.'],pitfalls:['Single huge upload request.']},
   {q:'Design multi-device sync with offline edits.',cover:['Journal and cursors; notifications.','Conflict detection by base version.','Conflict copies.'],pitfalls:['Last-write-wins silently.']},
   {q:'Storage costs are growing 60% a year. Design efficiency improvements.',lvl:'Staff+',cover:['Global dedup; content-defined chunking for better matches.','Tiering old versions; erasure coding.','Retention policies; compression.','Measure savings vs CPU costs.'],pitfalls:['Deleting user history.']}]});

P(12,{key:'Design Ticket Booking System like BookMyShow',short:'Ticket Booking',
  lead:'Design movie or event ticketing: browse shows, pick seats on a seat map, hold them for a few minutes while paying, and never sell a seat twice, even when a blockbuster opens and huge numbers try at once. Reports include Amazon SDE-2 (focus on consistency), an eBay variant with timed holds, and an L5 round focused on the database schema.',
  more:['The core is seat inventory per show. Selecting seats creates a hold: an atomic update from AVAILABLE to HELD with an expiry, protected by a conditional update, row lock or unique constraint on (show, seat). Payment converts the hold to BOOKED; expiry or failure releases it. For hot launches, a virtual waiting room meters users into the booking flow; holds may live in Redis with TTLs, backed by the database as the source of truth.'],
  clarify:[['Seat selection or general admission?','Seat selection.'],['Hold duration?','10 minutes.'],['Peak?','Blockbuster opening: 1 million users for 50,000 seats.'],['Payments?','External gateway.']],
  est:{dau:10e6,writes:0.3,ratio:30,size:500,years:3,peak:20,wlabel:'bookings',rlabel:'seat map views',unit:'booking'},
  build:B(['Seat inventory per show with status and hold expiry | Source of truth for seats.','Atomic hold (conditional update or unique constraint) | No double selling.','Hold expiry (TTL or sweeper) | Release unpaid seats.','Payment with idempotency, converting hold to booking | Correct completion.','Virtual waiting room for hot shows | Protect the system and keep it fair.','Cached show listings and seat maps (short TTL) | Read traffic.'],['Checking seat status then booking without atomicity | Double booking.','Holding seats forever until payment | Inventory locked by abandoned carts.','Eventual consistency on seat status | Two people pay for one seat.']),
  takeaway:'Model seats per show, hold them atomically with expiry, convert to bookings on idempotent payment, release on timeout, and meter hot launches through a waiting room.',
  pre:['ACID Transactions','Design a Hotel Reservation System','Rate limiting'],
  quiz:[{q:'How do you ensure two users cannot hold the same seat?',o:['Check then update','UPDATE seats SET status=HELD ... WHERE show=? AND seat=? AND status=AVAILABLE, and check rows affected','Use a cache only'],a:1,why:'Only one conditional update succeeds.',hint:'Atomic check and set.'},
        {q:'What is a virtual waiting room for?',o:['Showing trailers','Admitting users to the booking flow at a rate the system can handle, in fair order','Storing tickets'],a:1,why:'Turns a stampede into a queue.',hint:'Metering.'}],
  terms:[['Hold','Temporary reservation of seats with expiry.'],['Waiting room','Queue in front of a high-demand flow.'],['Seat map','Layout of seats and their status.']],
  deep:[{h:'Schema',ul:['shows(id, venue, time), seats(show_id, seat_id, status, hold_id, hold_expires_at, booking_id).','holds(id, user, show, seats, expires_at), bookings(id, user, show, seats, payment_id, status).','Unique (show_id, seat_id) on booking items.']},
   {h:'Hold and book',ul:['Hold all chosen seats in one transaction; all or none.','Pay with idempotency key = hold id.','On success: seats BOOKED; on failure or expiry: AVAILABLE.']},
   {h:'High demand',ul:['Waiting room tokens; per-user limits; bot defences.','Holds in Redis with Lua for speed, persisted on payment.','Partition by show.']},
   {h:'Edge cases',ul:['Payment succeeds after hold expired: re-check; refund if seats gone.','Partial seat availability: suggest alternatives.','Venue changes and cancellations.']}],
  iq:[{q:'Design the database schema and the seat hold transaction.',lvl:'Mid',cover:['Tables and keys.','Conditional updates; expiry.'],pitfalls:['No uniqueness enforcement.']},
   {q:'Design for a blockbuster: 1 million users for 50,000 seats in the first minute.',cover:['Waiting room; rate of admission.','Fast hold path (Redis or partitioned DB).','Payment throughput; fairness; bots.'],pitfalls:['Letting everyone hit the database.']},
   {q:'A payment succeeds 30 seconds after the hold expired and the seat was sold to someone else. Design the policy and mechanics.',lvl:'Staff+',cover:['Detect at confirmation; refund automatically or offer alternatives.','Reduce occurrence: extend holds while payment in flight; grace windows.','Reconciliation and customer communication.'],pitfalls:['Selling the seat twice.']}]});

P(12,{key:'Design Distributed Web Crawler',short:'Web Crawler',
  lead:'Design a crawler that downloads billions of web pages for a search engine or archive: discover URLs, fetch politely, avoid duplicates and traps, and keep content fresh. A Reddit senior round asked a version where users submit links, the crawler saves pages and notifies on completion, with follow-ups on queue failures and making sure every crawl finishes.',
  more:['The URL frontier holds URLs to fetch, prioritised by importance and freshness, and grouped by host so each site is fetched politely (respecting robots.txt and crawl delays). Fetchers download pages; parsers extract links and content; a URL-seen check (Bloom filter plus a store) and a content fingerprint check skip duplicates. Work is partitioned by host hash across many crawler nodes, and everything flows through durable queues so failures can be retried and progress tracked.'],
  clarify:[['Scale?','1 billion pages a month.'],['Content types?','HTML only.'],['Politeness?','robots.txt and per-host rate limits.'],['Freshness?','Recrawl important pages often.']],
  est:{dau:33e6,writes:1,ratio:1,size:500e3,years:1,peak:1,wlabel:'pages fetched',rlabel:'parses',unit:'page'},
  build:B(['URL frontier with priority and per-host queues | Politeness and importance ordering.','Distributed fetchers partitioned by host hash | Scale and keep one host on one worker.','robots.txt cache and per-host rate limits | Be a good citizen.','URL-seen filter (Bloom filter + store) and content fingerprints | Skip duplicates.','Parser and link extractor feeding the frontier | Discover new pages.','Durable queues with retries and progress tracking | Survive failures and finish every crawl.'],['One global FIFO queue | No politeness or priority.','Fetching every URL without dedup | Infinite loops and waste.','Following unlimited dynamic URLs | Spider traps.']),
  takeaway:'A prioritised, host-partitioned frontier with politeness, dedup by URL and content, durable queues for retries and progress, and defences against traps.',
  pre:['Message Queues','Bloom Filters','Consistent Hashing'],
  quiz:[{q:'Why partition crawling by host?',o:['Hosts demand it','So one worker controls the request rate to each site and politeness is easy to enforce','To save DNS lookups only'],a:1,why:'Rate limits per host need one owner.',hint:'Politeness.'},
        {q:'How do you avoid fetching the same URL twice cheaply?',o:['Check a SQL table each time','A Bloom filter in front of a persistent URL store','Never deduplicate'],a:1,why:'Fast negative checks for billions of URLs.',hint:'Probably seen?'}],
  terms:[['Frontier','Set of URLs waiting to be crawled.'],['robots.txt','Site rules for crawlers.'],['Spider trap','URL patterns that generate endless pages.']],
  deep:[{h:'Frontier',ul:['Front queues by priority; back queues per host.','Scheduler respects crawl delay per host.','Persisted so restarts lose nothing.']},
   {h:'Fetch and parse',ul:['DNS caching; connection reuse; timeouts.','Store raw pages in object storage.','Extract and normalise links; enqueue unseen URLs.']},
   {h:'Dedup and traps',ul:['URL normalisation; Bloom filter + store.','Content fingerprints (SimHash) for near-duplicates.','Depth and URL length limits; per-host page caps.']},
   {h:'Reliability and freshness',ul:['At-least-once processing; idempotent writes.','Track job progress for user-submitted crawls; notify on completion.','Recrawl schedule by change rate and importance.']}],
  iq:[{q:'Design a basic crawler and its main components.',lvl:'Mid',cover:['Frontier, fetcher, parser, dedup, storage.','Politeness.'],pitfalls:['No dedup.']},
   {q:'Users submit seed links; crawl their domains and notify them when done, guaranteeing every crawl finishes.',cover:['Crawl job record with counters of pending URLs.','Durable queues; retries; DLQ; timeouts per URL.','Completion detection when pending reaches zero; notification.','Handling worker crashes.'],pitfalls:['No way to know when a crawl ends.']},
   {q:'Scale to 10 billion pages a month across data centers.',lvl:'Staff+',cover:['Partition hosts across data centers by geography.','Frontier sharding; storage throughput.','Bandwidth and cost; politeness at scale.','Monitoring for traps and spam.'],pitfalls:['A central frontier for all regions.']}]});

P(12,{key:'Design Code Deployment System',short:'Code Deployment',
  lead:'Design a system that builds code and deploys it to thousands of servers safely: build once, roll out gradually with health checks, and roll back quickly when something goes wrong.',
  more:['A pipeline turns a commit into an immutable, versioned artifact (container image or package) stored in a registry. Deployment rolls that artifact out in stages: canary to a few servers, then a percentage of a region, then all regions, with automated health checks (error rates, latency) gating each stage and triggering automatic rollback. Distribution of large artifacts to thousands of hosts can use peer-to-peer or regional caches. Deploy state is tracked durably so a controller crash does not leave the fleet in an unknown state.'],
  clarify:[['Fleet size?','Assume 50,000 servers in 10 regions.'],['Frequency?','Hundreds of deploys a day across services.'],['Rollback time?','Minutes.'],['Strategies?','Rolling, canary, blue-green.']],
  est:null,noest:'The key numbers are fleet size, artifact size and rollout time: for example a 1 GB artifact to 50,000 hosts is 50 TB of transfer, which pushes you to regional caches or peer-to-peer distribution. Focus on safety, state and distribution.',
  build:B(['Build service producing immutable versioned artifacts | Deploy exactly what was tested.','Artifact registry with regional replicas or P2P distribution | Fast, scalable downloads.','Deployment controller with durable rollout state | Resume or roll back after failures.','Staged rollout (canary, waves, regions) | Limit blast radius.','Automated health gates and rollback | Catch bad releases quickly.','Agents on hosts that pull and switch versions | Reliable execution on each machine.'],['Building on every server during deploy | Slow and inconsistent.','Deploying to all servers at once | One bad build takes everything down.','Manual rollback by SSH | Slow and error-prone.']),
  takeaway:'Build immutable artifacts once, distribute them efficiently, roll out in stages gated by health metrics, keep rollout state durable, and make rollback automatic.',
  pre:['Peer-to-Peer (P2P) Architecture','Distributed Tracing','Circuit Breaker'],
  quiz:[{q:'Why build an artifact once and deploy the same artifact everywhere?',o:['Saves disk','So what was tested is exactly what runs, and rollback is just switching versions','Required by Docker'],a:1,why:'Immutability gives reproducibility.',hint:'Same bits.'},
        {q:'What is a canary deployment?',o:['A test environment','Releasing to a small slice of production first and checking health before continuing','A backup server'],a:1,why:'Limits damage from a bad release.',hint:'Small first.'}],
  terms:[['Artifact','Built, versioned output deployed as-is.'],['Canary','Small first stage of a rollout.'],['Blue-green','Two environments; switch traffic between them.']],
  deep:[{h:'Build',ul:['Triggered by merge; hermetic builds; tests; signing.','Artifacts tagged by commit; stored in registry.','Provenance and supply-chain checks.']},
   {h:'Rollout',ul:['Plan: waves by percentage and region; bake time between waves.','Health gates from metrics and alerts; automatic pause or rollback.','Concurrency limits per service.']},
   {h:'Distribution',ul:['Regional registry mirrors; host caches.','P2P (BitTorrent-like) for huge artifacts.','Pre-fetch before switching.']},
   {h:'State and safety',ul:['Desired vs actual state per host; reconciliation loop.','Controller is stateless over a durable store.','Freeze windows; audit logs; approvals for risky services.']}],
  iq:[{q:'Design a rolling deployment with health checks.',lvl:'Mid',cover:['Batches, health checks, rollback.'],pitfalls:['All at once.']},
   {q:'Design artifact distribution to 50,000 hosts within 10 minutes.',cover:['Bandwidth math; regional mirrors; P2P.','Integrity checks; throttling.'],pitfalls:['Single registry.']},
   {q:'Design a deployment platform used by 500 teams with different risk profiles.',lvl:'Staff+',cover:['Policy-driven rollout templates per tier.','Automatic analysis (canary scoring).','Change management, freeze windows, audit.','Self-service with guardrails; metrics on change failure rate.'],pitfalls:['One rollout policy for everyone.']}]});

P(12,{key:'Design Distributed Cloud Storage like S3',short:'Object Storage (S3)',
  lead:'Design object storage like Amazon S3: store and retrieve objects of any size by bucket and key over HTTP, with eleven nines of durability, high availability, and effectively unlimited scale.',
  more:['Separate metadata from data. A metadata service maps (bucket, key, version) to the locations of the object\'s data chunks and must be strongly consistent (S3 has been strongly consistent for reads after writes since 2020). Data nodes store chunks durably using replication or erasure coding (for example 6 data + 3 parity chunks spread across failure domains), with checksums and background scrubbing to detect and repair corruption. Large uploads use multipart upload; reads can fetch ranges.'],
  clarify:[['Object sizes?','Bytes to terabytes.'],['Durability?','99.999999999% (eleven nines).'],['Consistency?','Strong read-after-write.'],['Features?','Versioning, multipart upload, lifecycle rules.']],
  est:{dau:10e6,writes:100,ratio:3,size:1e6,years:5,peak:3,wlabel:'object writes',rlabel:'object reads',unit:'object'},
  build:B(['Front-end API servers (stateless) | Authenticate, route, stream data.','Metadata service, sharded and strongly consistent | Map keys to chunk locations.','Data nodes storing chunks with erasure coding across failure domains | Durability at lower cost than 3x replication.','Placement service choosing nodes by capacity and failure domain | Balanced, safe placement.','Checksums and background scrubbing and repair | Detect and fix silent corruption.','Multipart upload and range reads | Large objects.'],['Storing objects in a relational database | Size and throughput.','Single-copy storage | Durability target impossible.','Eventually consistent metadata with no read-after-write | Surprising for clients.']),
  takeaway:'Stateless front ends, a strongly consistent sharded metadata service, erasure-coded data across failure domains, and continuous checksumming and repair.',
  pre:['Checksums','Database Replication','Consistent Hashing'],
  quiz:[{q:'Why use erasure coding instead of 3 full copies?',o:['It is faster to read','It gives similar or better durability with much less storage overhead (for example 1.5x instead of 3x)','It avoids checksums'],a:1,why:'Parity chunks reconstruct lost data.',hint:'Storage overhead.'},
        {q:'What does background scrubbing do?',o:['Deletes old objects','Reads stored chunks, verifies checksums, and repairs corrupted ones from redundancy','Compresses data'],a:1,why:'Disks silently corrupt data over time.',hint:'Bit rot.'}],
  terms:[['Erasure coding','Data plus parity chunks that can rebuild missing chunks.'],['Failure domain','Unit that can fail together (disk, rack, zone).'],['Multipart upload','Uploading a large object in parts.']],
  deep:[{h:'Write path',ul:['Authenticate; choose placement; stream chunks to data nodes with checksums.','Encode with erasure coding across zones.','Commit metadata atomically; return success.']},
   {h:'Read path',ul:['Lookup metadata; fetch chunks (or enough to decode).','Verify checksums; range requests.','Caching for hot objects.']},
   {h:'Metadata',ul:['Partitioned by bucket and key prefix; consensus-replicated.','Listing by prefix needs ordered keys.','Versioning and lifecycle rules.']},
   {h:'Durability operations',ul:['Scrubbing; repair on node loss with throttling.','Spread across racks and zones.','Durability math from failure rates and repair time.']}],
  iq:[{q:'Describe the write and read paths for an object.',lvl:'Mid',cover:['Metadata vs data.','Placement, checksums.'],pitfalls:['Single node storage.']},
   {q:'How do you reach eleven nines of durability?',cover:['Redundancy across failure domains; erasure coding.','Fast repair; scrubbing; checksums end to end.','Durability math intuition.'],pitfalls:['Only RAID on one machine.']},
   {q:'Design strongly consistent listing and read-after-write for a metadata layer with trillions of keys.',lvl:'Staff+',cover:['Sharded ordered metadata with consensus per shard.','Prefix partitioning and splitting hot prefixes.','Caches with invalidation that preserves consistency (witness or version checks).','Performance targets.'],pitfalls:['Eventual metadata with caches.']}]});

P(12,{key:'Design Distributed Locking Service',short:'Lock Service',
  lead:'Design a lock service like Google\'s Chubby or etcd that many applications use for leader election, mutual exclusion and small configuration, with strong consistency and high availability.',
  more:['The service is a small replicated state machine run on consensus (Paxos or Raft) across 5 nodes in different failure domains. Clients open sessions kept alive by heartbeats; locks are held under sessions with leases and released if the session expires. Every lock grant returns a fencing token (a monotonically increasing number) that clients pass to the resources they protect. Clients can watch keys for changes. Reads go through the leader or use lease-based optimisations; the service is optimised for availability and correctness, not high throughput.'],
  clarify:[['Use cases?','Leader election, mutual exclusion, small config.'],['Scale?','Thousands of clients, tens of thousands of locks.'],['Consistency?','Linearizable.'],['Failure tolerance?','Survive 2 node failures.']],
  est:null,noest:'Throughput is small (thousands of operations per second); the design is about correctness: consensus, sessions, leases, fencing tokens and watches.',
  build:B(['Consensus cluster (Raft/Paxos) of 5 nodes across zones | Linearizable, survives 2 failures.','Sessions with keepalive heartbeats | Detect dead clients and release their locks.','Leases on locks | Bounded hold time when clients fail.','Fencing tokens returned on every grant | Protect resources from stale holders.','Watches/notifications on keys | Clients react to changes without polling.','Client library with retries and session handling | Correct use by many teams.'],['Single Redis instance as the lock store | Loses locks on failover; no fencing.','Locks without expiry | A crashed client blocks forever.','Gossip-based lock decisions | Not strongly consistent.']),
  takeaway:'A small consensus-replicated store with sessions, leases, fencing tokens and watches, packaged in a client library that makes correct use easy.',
  pre:['Distributed Locking','Consensus Algorithms','HeartBeats'],
  quiz:[{q:'Why run the lock service on 5 nodes rather than 4?',o:['More throughput','5 tolerates 2 failures; 4 tolerates only 1, like 3','Odd numbers are faster'],a:1,why:'Majority of 5 is 3.',hint:'Majority math.'},
        {q:'What protects a resource when a lock holder pauses past its lease?',o:['Longer leases','Fencing tokens checked by the resource','Faster clients'],a:1,why:'The resource rejects older tokens.',hint:'Who checks?'}],
  terms:[['Session','Client connection state kept alive by heartbeats.'],['Watch','Notification when a key changes.'],['Fencing token','Increasing number issued with each lock grant.']],
  deep:[{h:'Core',ul:['Raft log of operations; state machine of keys, locks, sessions.','Writes committed by majority; reads via leader with read index.','Snapshots and log compaction.']},
   {h:'Sessions and leases',ul:['Client keepalives; session TTL.','Locks tied to sessions; released on expiry.','Grace periods during leader failover.']},
   {h:'API',ul:['Acquire(lock) returns token; Release; TryAcquire with timeout.','Get/Put small values; Watch(prefix).','Leader election helper built on locks.']},
   {h:'Operations',ul:['5 nodes in 3+ zones.','Client-side caching with invalidation (Chubby).','Quotas per tenant; monitoring of leader changes.']}],
  iq:[{q:'Design leader election using a lock service.',lvl:'Mid',cover:['Acquire lock with session; leader renews; others watch.','Failover on expiry.'],pitfalls:['No fencing.']},
   {q:'Design the lock service internals.',cover:['Consensus, sessions, leases, fencing, watches.','Failure scenarios.'],pitfalls:['Single node.']},
   {q:'Hundreds of teams misuse the lock service for high-throughput coordination and it is overloaded. What do you do?',lvl:'Staff+',cover:['Quotas and rate limits per tenant; usage visibility.','Guidance and alternatives (partitioning, idempotency).','Client library defaults (caching, backoff).','Capacity and isolation (separate clusters for critical users).'],pitfalls:['Simply adding more nodes (makes writes slower).']}]});

/* Extras from the book notes */
P(12,{key:'Design Ad Click Event Aggregation',short:'Ad Click Aggregation',
  lead:'Count clicks per ad in real time (for example per minute) for billing and dashboards, at billions of clicks per day, with exactly-once correctness, late events and fraud filtering.',
  more:['Click events land in Kafka, are deduplicated by click id, and aggregated by a stream processor (Flink) into per-ad, per-minute windows using event time with watermarks for late arrivals. Results go to an OLAP store for queries. Raw events are kept so a batch job can recompute and reconcile totals (billing-grade accuracy). Exactly-once comes from checkpointed state plus transactional or idempotent sinks.'],
  clarify:[['Scale?','10 billion clicks a day.'],['Latency?','Minute-level aggregates within a few minutes.'],['Accuracy?','Exact for billing after reconciliation.'],['Queries?','Clicks per ad over time; top ads.']],
  est:{dau:1e9,writes:10,ratio:0.01,size:200,years:1,peak:3,wlabel:'clicks',rlabel:'aggregate queries',unit:'click event'},
  build:B(['Kafka ingestion partitioned by ad id | Durable, ordered per ad.','Stream processor with event-time windows and watermarks | Correct minute counts despite lateness.','Dedup by click id | No double counting.','Checkpointed state with exactly-once sinks | Correct after failures.','OLAP store for aggregates | Fast queries.','Raw event storage and batch reconciliation | Billing-grade accuracy.'],['Incrementing a database counter per click | Hot keys and no replay.','Processing-time windows only | Late events counted in wrong windows.','Deleting raw events after streaming | No way to correct mistakes.']),
  takeaway:'Stream clicks through Kafka into event-time windowed aggregation with dedup and checkpointing, serve from an OLAP store, and reconcile with batch over raw events.',
  pre:['Batch vs Stream Processing','Message Brokers','Idempotency'],
  quiz:[{q:'Why use event time rather than processing time?',o:['It is simpler','Clicks can arrive late; event time places them in the minute they happened','Processing time is not available'],a:1,why:'Billing must reflect when the click occurred.',hint:'Late arrivals.'},
        {q:'Why keep raw click events?',o:['Legal requirement only','To recompute aggregates after bugs and reconcile billing','To show users'],a:1,why:'Replay makes the pipeline correctable.',hint:'Fix mistakes.'}],
  terms:[['Event time','When the event happened.'],['Watermark','Progress marker for event time.'],['OLAP','Analytical database for aggregates.']],
  deep:[{h:'Pipeline',ul:['Clicks to Kafka by ad id.','Flink job: dedup, filter fraud, window by minute, aggregate.','Sink to OLAP (Druid, Pinot, ClickHouse) idempotently.']},
   {h:'Correctness',ul:['Exactly-once via checkpoints and transactional sinks.','Allowed lateness; late updates to closed windows.','Reconciliation batch daily.']},
   {h:'Hot ads',ul:['Pre-aggregate on partitions; key splitting for very hot ads.','Combine partial counts.']},
   {h:'Queries',ul:['Rollups (minute, hour, day).','Top-N with approximate algorithms if needed.']}],
  iq:[{q:'Design minute-level click counts per ad.',lvl:'Mid',cover:['Stream, window, aggregate, store.'],pitfalls:['Counter per click in a DB.']},
   {q:'How do you achieve exactly-once counts across failures?',cover:['Dedup ids; checkpoints; idempotent or transactional sinks.','Replay from offsets.'],pitfalls:['Hoping failures are rare.']},
   {q:'Design reconciliation between streaming aggregates and billing.',lvl:'Staff+',cover:['Raw events in a lake; batch recount.','Diff and correct; audit trail.','SLA for final numbers.'],pitfalls:['Billing directly from streaming output.']}]});

P(12,{key:'Design a Stock Exchange',short:'Stock Exchange',
  lead:'Design an exchange that accepts buy and sell orders, matches them by price and time priority, publishes market data, and does it with microsecond latency, determinism and fairness.',
  more:['The matching engine keeps an order book per symbol (bids and asks sorted by price, then time) in memory on a single thread per symbol, which avoids locks and makes processing deterministic. Orders arrive through gateways (risk checks), are sequenced into a log (the sequencer gives every event a global order), and the matching engine processes the log; replicas replay the same log to stay identical (event sourcing), enabling fast failover. Market data is published by multicast. Colocation and kernel-bypass networking keep latency tiny.'],
  clarify:[['Symbols and volume?','Thousands of symbols; billions of orders a day.'],['Latency?','Microseconds inside the exchange.'],['Order types?','Limit and market; cancel.'],['Fairness?','Strict price-time priority.']],
  est:{dau:1e5,writes:50000,ratio:10,size:100,years:7,peak:10,wlabel:'orders',rlabel:'market data messages',unit:'order event'},
  build:B(['Order gateways with risk checks | Validate and protect.','Sequencer producing a totally ordered event log | Determinism and fairness.','Single-threaded in-memory matching engine per symbol | Lock-free, deterministic matching.','Replicated engines replaying the log (event sourcing) | Hot standby with identical state.','Market data publisher via multicast | Fair, low-latency distribution.','Durable log storage and reporting systems | Audit and settlement.'],['A relational database transaction per order | Far too slow.','Multi-threaded matching with locks on the book | Non-deterministic and slower.','Eventual consistency for fills | Unacceptable for trades.']),
  takeaway:'Sequence every event into one ordered log, match on a single thread per symbol in memory, replicate by replaying the log, and publish market data by multicast.',
  pre:['Event-Driven Architecture','Consensus Algorithms','Latency vs Throughput'],
  quiz:[{q:'Why a single thread per symbol?',o:['Cheaper hardware','No locks and deterministic results: same input order always gives the same trades','Threads are forbidden'],a:1,why:'Determinism enables replay and replicas.',hint:'Order of events.'},
        {q:'How does a standby engine take over instantly?',o:['Restore from yesterday\'s backup','It replays the same sequenced log continuously, so its state is identical','It asks traders'],a:1,why:'Event sourcing with deterministic processing.',hint:'Same log, same state.'}],
  terms:[['Order book','Sorted bids and asks for a symbol.'],['Price-time priority','Best price first, then earliest.'],['Sequencer','Assigns a total order to events.']],
  deep:[{h:'Matching',ul:['Bids max-heap or sorted by price levels with FIFO queues.','Incoming order matches against the opposite side; remainder rests.','Cancel and modify operations.']},
   {h:'Sequencing and replication',ul:['All inputs go through the sequencer to a log.','Primary and standbys consume the same log.','Snapshots to speed recovery.']},
   {h:'Latency',ul:['Colocation, kernel bypass, busy polling, pre-allocated memory.','Avoid garbage collection pauses.','Measure in microseconds at p99.9.']},
   {h:'Downstream',ul:['Market data multicast; recovery channels.','Clearing and settlement systems consume trades.','Surveillance and audit.']}],
  iq:[{q:'Implement an order book with price-time priority.',lvl:'Mid',cover:['Data structures; matching logic.'],pitfalls:['Sorting all orders per event.']},
   {q:'Design the exchange architecture for determinism and failover.',cover:['Gateways, sequencer, matching, replicas.','Event log and replay.'],pitfalls:['A database at the core.']},
   {q:'Ensure fairness so no participant gets market data or order entry earlier than others.',lvl:'Staff+',cover:['Equal-length cables and colocation policies.','Multicast with simultaneous delivery; latency equalisation.','Auditing and monitoring.'],pitfalls:['Ignoring physical network fairness.']}]});
tagTier(12,'Hard');
